// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 depositTime, uint256 ts, uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        ts = bound(ts, 1, 2 days);
        amount = bound(amount, 1, 100 ether);
        vm.warp(ts);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(depositTime);

        (uint256 unlockTime,) = c.Acc(actor);
        assertTrue(unlockTime >= block.timestamp);
    }
}
